cd ~ && H=/efs/home/__USER__; for i in $(seq 1 12); do ls /efs/home >/dev/null 2>&1; [ -e "$H" ] && break; sleep 2; done; UID_NUM=$(stat -c %u "$H" 2>/dev/null); GID_NUM=$(stat -c %g "$H" 2>/dev/null); if [ -z "$UID_NUM" ] || [ -z "$GID_NUM" ]; then echo "secondary: ERROR /efs/home/__USER__ not visible from this bastion (do both bastions mount the same EFS?)"; else echo "secondary: mirroring __USER__ uid=$UID_NUM gid=$GID_NUM"; GERR=$(groupadd -g "$GID_NUM" __USER__ 2>&1) || echo "secondary: groupadd failed: $GERR"; UERR=$(useradd -u "$UID_NUM" -g "$GID_NUM" -M -d "$H" __USER__ 2>&1) || echo "secondary: useradd failed: $UERR"; fi; if id __USER__ >/dev/null 2>&1; then echo "secondary: __USER__ ready"; else echo "secondary: FAILED to create __USER__"; echo "secondary: uid ${UID_NUM:-?} held by: $(getent passwd "${UID_NUM:-}" 2>/dev/null || echo nobody)"; echo "secondary: gid ${GID_NUM:-?} held by: $(getent group "${GID_NUM:-}" 2>/dev/null || echo nobody)"; echo "secondary: group __USER__ is: $(getent group __USER__ 2>/dev/null || echo absent)"; fi